// GENERATED by fsp from config/: edit config/app.yaml, config/app.demo-dpop.yaml, config/app.keycloak.yaml and config/app.keycloak-dpop.yaml, not this file.
// Every value here is compiled into the app, where anyone who has the app can read it: never a
// secret (docs/app-config.md).
// ignore_for_file: type=lint, unused_element

const String _requested = String.fromEnvironment('FSP_PROFILE');
const String _flavor = String.fromEnvironment('FLUTTER_APP_FLAVOR');

/// The active profile: FSP_PROFILE (`fsp dev --profile`, `fsp build --profile`), else the
/// flavour (`--flavor`) when a profile has its name, else `dev` in a debug build when there is
/// a `dev` profile, else `default`.
const String _profile = bool.hasEnvironment('FSP_PROFILE')
    ? (_requested == '' ? 'default' : _requested)
    : _flavor == 'demo-dpop' || _flavor == 'keycloak' || _flavor == 'keycloak-dpop'
    ? _flavor
    : 'default';

/// A build whose FSP_PROFILE names no profile of config/ stops here, since dividing by zero is an
/// error in a constant. The profiles: `default`, `demo-dpop`, `keycloak`, `keycloak-dpop`.
const int _fspProfileNamesNoFileOfConfig =
    1 ~/
    (_profile == 'default' || _profile == 'demo-dpop' || _profile == 'keycloak' || _profile == 'keycloak-dpop'
        ? 1
        : 0);

/// The values of config/app.yaml, with those of the active profile over them.
abstract final class AppConfig {
  /// The active profile: `default` (config/app.yaml alone), `demo-dpop`, `keycloak` or `keycloak-dpop`.
  static const String profile = _profile;

  /// Where the app signs in. Empty: the demo API's own sign-in form, in process, with no OpenID
  /// Connect. `demo`: OpenID Connect against the demo server's own provider, in process (no
  /// Keycloak, no browser, no network). A URL: a Keycloak realm (keycloak/realm-fespalier.json).
  ///
  /// `oidc.issuer` in config/app.yaml; set by `demo-dpop`, `keycloak` and `keycloak-dpop`.
  static const String oidcIssuer = _profile == 'demo-dpop'
      ? 'demo'
      : _profile == 'keycloak'
      ? 'http://localhost:8080/realms/fespalier'
      : _profile == 'keycloak-dpop'
      ? 'http://localhost:8080/realms/fespalier'
      : '';

  /// The Keycloak client: a public client, with PKCE.
  ///
  /// `oidc.client_id` in config/app.yaml; set by `keycloak-dpop`.
  static const String oidcClientId = _profile == 'keycloak-dpop'
      ? 'fespalier-auth-example-dpop'
      : 'fespalier-auth-example';

  /// Where Keycloak sends the browser back to: registered with the client.
  ///
  /// `oidc.redirect` in config/app.yaml.
  static const String oidcRedirect = 'com.example.fespalierauth:/callback';

  /// Bind the tokens to a device key (DPoP, RFC 9449). Needs an `oidc.issuer`; against Keycloak, with
  /// the client that requires it (`fespalier-auth-example-dpop`).
  ///
  /// `dpop` in config/app.yaml; set by `demo-dpop` and `keycloak-dpop`.
  static const bool dpop = _profile == 'demo-dpop'
      ? true
      : _profile == 'keycloak-dpop'
      ? true
      : false;
}
